import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';

// POST /api/enquiry — Submit a contact us enquiry (public, no auth)
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { name, email, phone, subject, message } = body;

    if (!name || !email || !message) {
      return NextResponse.json({ error: 'Name, email and message are required' }, { status: 400 });
    }

    const enquiry = await (db as any).enquiry.create({
      data: { name, email, phone: phone || '', subject: subject || 'General Enquiry', message }
    });

    // Notify all active cashiers & super admins (fire-and-forget)
    db.user.findMany({ where: { role: { in: ['CASHIER', 'SUPER_ADMIN'] }, isActive: true }, select: { id: true } })
      .then(async (users) => {
        if (users.length > 0) {
          await db.notification.createMany({
            data: users.map(u => ({
              userId: u.id,
              type: 'NEW_ENQUIRY',
              title: 'New Customer Enquiry',
              message: `${name} (${phone || email}) submitted an enquiry: ${message.substring(0, 100)}${message.length > 100 ? '...' : ''}`,
              data: JSON.stringify({ enquiryId: enquiry.id, email, phone })
            }))
          });
        }
      }).catch(err => console.error('[Enquiry] Notification failed (non-critical):', err));

    return NextResponse.json({ success: true, enquiry });
  } catch (error) {
    console.error('[Enquiry] POST error:', error);
    return NextResponse.json({ error: 'Failed to submit enquiry' }, { status: 500 });
  }
}


// GET /api/enquiry — Fetch enquiries (cashier/SA only)
// Merges BOTH Enquiry table (new) + ContactEnquiry table (old landing-page submissions)
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const status = searchParams.get('status');
    const take = parseInt(searchParams.get('take') || '100');

    const where: any = {};
    if (status) where.status = status;

    // Fetch from both tables in parallel
    const [newEnquiries, oldEnquiries] = await Promise.all([
      (db as any).enquiry.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        take
      }),
      db.contactEnquiry.findMany({
        where: status ? { status } : {},
        orderBy: { createdAt: 'desc' },
        take
      })
    ]);

    // Normalize ContactEnquiry records to match Enquiry shape
    const normalizedOld = oldEnquiries.map((e: any) => ({
      ...e,
      subject: 'General Enquiry',       // ContactEnquiry has no subject
      seenByCashier: false,
      seenBySA: false,
      resolvedNote: e.notes || null,
      _source: 'contact_enquiry'         // mark origin for PATCH routing
    }));

    // Merge, sort newest first, cap at take
    const merged = [...newEnquiries, ...normalizedOld]
      .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
      .slice(0, take);

    const pendingCount = merged.filter((e: any) => e.status === 'PENDING').length;

    return NextResponse.json({ success: true, enquiries: merged, pendingCount });
  } catch (error) {
    console.error('[Enquiry] GET error:', error);
    return NextResponse.json({ error: 'Failed to fetch enquiries' }, { status: 500 });
  }
}


// PATCH /api/enquiry — Update status
export async function PATCH(request: NextRequest) {
  try {
    const body = await request.json();
    const { id, status, seenByCashier, seenBySA, resolvedNote, resolvedBy } = body;

    if (!id) return NextResponse.json({ error: 'ID required' }, { status: 400 });

    const updateData: any = {};
    if (status) { updateData.status = status; }
    if (seenByCashier !== undefined) updateData.seenByCashier = seenByCashier;
    if (seenBySA !== undefined) updateData.seenBySA = seenBySA;
    if (resolvedNote) {
      updateData.resolvedNote = resolvedNote;
      updateData.resolvedBy = resolvedBy;
      updateData.resolvedAt = new Date();
      updateData.status = 'RESOLVED';
    }

    const enquiry = await (db as any).enquiry.update({
      where: { id },
      data: updateData
    });

    return NextResponse.json({ success: true, enquiry });
  } catch (error) {
    console.error('[Enquiry] PATCH error:', error);
    return NextResponse.json({ error: 'Failed to update enquiry' }, { status: 500 });
  }
}
